import re
from typing import Any

CONFLICTING_DOMAINS = {
    "sun": ["solar", "day", "light", "dawn"],
    "death": ["underworld", "mortality", "necromancy", "afterlife"],
    "war": ["battle", "strife", "conquest", "wrath"],
    "ocean": ["sea", "tides", "depths", "storms"]
}

def hook_validate_entity(entity_data: dict[str, Any], context: dict[str, Any]) -> list[dict[str, Any]]:
    diagnostics = []
    etype = str(entity_data.get("type", "")).lower()
    name = entity_data.get("name", "Unnamed Entity")

    if etype in ("deity", "god", "goddess", "demigod", "pantheon"):
        domains = entity_data.get("domains", [])
        if isinstance(domains, str):
            domains = [d.strip() for d in domains.split(",")]

        if not domains:
            diagnostics.append({
                "severity": "warning",
                "message": f"Deity '{name}' has no defined divine domains or portfolio.",
                "target": name,
                "details": {"recommendation": "Specify domains such as 'Sun, Justice, Metallurgy' in frontmatter."}
            })

        alignment = entity_data.get("alignment", None)
        worship_tier = entity_data.get("worship_tier", None)
        if worship_tier and str(worship_tier).lower() not in ("local", "national", "continental", "cosmic", "primordial"):
            diagnostics.append({
                "severity": "info",
                "message": f"Deity '{name}' uses non-standard worship tier '{worship_tier}'.",
                "target": name
            })

    return diagnostics

def hook_custom_metric(text: str, context: dict[str, Any]) -> dict[str, Any]:
    prayers = len(re.findall(r"\b(pray|prayed|prayer|supplication|altar|sacrifice|deity|gods|goddess)\b", text, re.I))
    return {"mythic_pantheon_piety_references": prayers}

