def hook_custom_metric(text: str, context: dict[str, Any]) -> dict[str, Any]:
    apostrophes = len(re.findall(r"[a-zA-Z]'[a-zA-Z]", text))
    foreign_italics = len(re.findall(r"\*[a-zA-Z]+\*|_([a-zA-Z]+)_", text))
    return {
        "linguistic_apostrophe_glottal_stops": apostrophes,
        "linguistic_italicized_terms": foreign_italics
    }

import re
from typing import Any

CLICHE_PATTERNS = [
    (r"chosen one", "Prophecy fatigue: consider inverting who the prophecy refers to or making it a fabricated political tool."),
    (r"ancient evil awakens", "Awakened evil trope: consider making the 'evil' an ancient misunderstood technological defense system."),
    (r"dark lord", "Monolithic villainy: give the antagonist clear economic, theological, or philosophical justifications."),
    (r"orphan boy with a mysterious birthmark", "Hero origin cliché: anchor the protagonist's drive in communal responsibility rather than bloodline entitlement.")
]

def hook_validate_manuscript(manuscript_data: dict[str, Any], context: dict[str, Any]) -> list[dict[str, Any]]:
    diagnostics = []
    chapters = manuscript_data.get("chapters", [])
    for ch in chapters:
        title = ch.get("title", "Chapter")
        text = ch.get("content", "")
        for pat, advice in CLICHE_PATTERNS:
            if re.search(r"\b" + pat + r"\b", text, re.IGNORECASE):
                diagnostics.append({
                    "severity": "info",
                    "message": f"Detected classic trope pattern '{pat}' in {title}. Subversion prompt: {advice}",
                    "target": title
                })
    return diagnostics

def hook_custom_metric(text: str, context: dict[str, Any]) -> dict[str, Any]:
    hits = 0
    for pat, _ in CLICHE_PATTERNS:
        hits += len(re.findall(r"\b" + pat + r"\b", text, re.I))
    return {"trope_inversion_opportunity_count": hits}

