import re
from typing import Any

def hook_validate_entity(entity_data: dict[str, Any], context: dict[str, Any]) -> list[dict[str, Any]]:
    diagnostics = []
    v_c = entity_data.get("velocity_fraction_c", None)
    name = entity_data.get("name", "Vessel")
    if v_c is not None:
        try:
            v = float(v_c)
            if v >= 1.0:
                diagnostics.append({
                    "severity": "error",
                    "message": f"Vessel '{name}' has sub-light velocity >= 1.0c ({v}c). Relativistic singularity violation.",
                    "target": name
                })
            elif v > 0.999:
                diagnostics.append({
                    "severity": "warning",
                    "message": f"Vessel '{name}' travels at extreme relativistic speed ({v}c). Lorentz factor gamma > 22.3.",
                    "target": name
                })
        except ValueError:
            pass
    return diagnostics

def hook_custom_metric(text: str, context: dict[str, Any]) -> dict[str, Any]:
    matches = len(re.findall(r"\b(light-year|lightyear|parsec|dilation|lorentz|gamma factor|sub-light)\b", text, re.I))
    return {"hard_sf_chronometry_terms": matches}
